// Generates the desktop theme, the Rust token constants and the phone theme from tokens.json.
//
//   node design/tokens/build.mjs          write the generated files
//   node design/tokens/build.mjs --check  fail if a generated file is out of date (for CI)

import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, '..', '..');
const tokens = JSON.parse(readFileSync(join(here, 'tokens.json'), 'utf8'));
const HEADER = 'Generated by design/tokens/build.mjs from design/tokens/tokens.json. Do not edit.';

// --------------------------------------------------------------------------------------------
// Helpers
// --------------------------------------------------------------------------------------------

/** "#RRGGBB" or "#RRGGBBAA" → "0xRRGGBBAA". */
function rgbaLiteral(hex) {
  const digits = hex.slice(1).toUpperCase();
  if (!/^([0-9A-F]{6}|[0-9A-F]{8})$/.test(digits)) {
    throw new Error(`Not a colour: ${hex}`);
  }
  return `0x${digits.length === 6 ? `${digits}FF` : digits}`;
}

const snake = (name) => name.replace(/[A-Z]/g, (letter) => `_${letter.toLowerCase()}`);
const constant = (name) => snake(name).replace(/\./g, '_').toUpperCase();
const float = (value) => (Number.isInteger(value) ? `${value}.0` : `${value}`);

/** Converts an Apple-style spring (response, damping fraction) to stiffness and damping at mass 1. */
function springPhysics({ response, dampingFraction }) {
  const stiffness = (2 * Math.PI / response) ** 2;
  const damping = (4 * Math.PI * dampingFraction) / response;
  return {
    response,
    dampingFraction,
    mass: 1,
    stiffness: Math.round(stiffness * 100) / 100,
    damping: Math.round(damping * 100) / 100,
  };
}

// --------------------------------------------------------------------------------------------
// Desktop: a GPUI Kit theme file
// --------------------------------------------------------------------------------------------

function kitColors(c, mode) {
  return {
    background: c.background,
    foreground: c.text,
    border: c.border,
    'input.border': c.borderStrong,
    ring: c.accent,
    caret: c.text,

    'primary.background': c.primary,
    'primary.hover.background': c.primaryHover,
    'primary.active.background': c.primaryActive,
    'primary.foreground': c.primaryForeground,

    'secondary.background': c.surfaceRaised,
    'secondary.hover.background': c.surfaceHover,
    'secondary.active.background': c.surfaceActive,
    'secondary.foreground': c.text,

    'accent.background': c.surfaceHover,
    'accent.foreground': c.text,
    'muted.background': c.surfaceRaised,
    'muted.foreground': c.textMuted,
    'popover.background': c.surfaceRaised,
    'popover.foreground': c.text,

    'danger.background': c.danger,
    'danger.foreground': c.dangerForeground,
    'success.background': c.live,
    'success.foreground': c.liveForeground,
    'warning.background': c.warning,
    'warning.foreground': c.warningForeground,
    'info.background': c.accent,
    'info.foreground': c.accentForeground,

    link: c.accent,
    'link.hover': c.accentHover,
    'link.active': c.accentActive,
    'selection.background': c.selection,

    'list.background': c.background,
    'list.hover.background': c.surfaceHover,
    'list.active.background': c.selection,
    'list.active.border': c.accent,
    'list.even.background': c.background,
    'list.head.background': c.surface,

    'sidebar.background': c.surface,
    'sidebar.foreground': c.text,
    'sidebar.border': c.border,
    'sidebar.accent.background': c.surfaceHover,
    'sidebar.accent.foreground': c.text,
    'sidebar.primary.background': c.primary,
    'sidebar.primary.foreground': c.primaryForeground,

    'title_bar.background': c.background,
    'title_bar.border': c.border,
    'tab_bar.background': c.background,
    'tab_bar.segmented.background': c.surfaceRaised,
    'tab.background': c.scrim,
    'tab.foreground': c.textMuted,
    'tab.active.background': c.surfaceActive,
    'tab.active.foreground': c.text,

    'group_box.background': c.surface,
    'group_box.foreground': c.text,
    'accordion.background': c.background,
    'accordion.hover.background': c.surfaceHover,
    'skeleton.background': c.surfaceRaised,
    'progress.bar.background': c.primary,
    'slider.background': c.primary,
    'slider.thumb.background': mode === 'dark' ? c.background : c.surfaceRaised,
    'switch.background': c.surfaceActive,
    'switch.thumb.background': c.background,

    'scrollbar.background': c.scrim,
    'scrollbar.thumb.background': c.borderStrong,
    'scrollbar.thumb.hover.background': c.textSubtle,
    'drag.border': c.accent,
    'drop_target.background': c.selection,
    overlay: c.overlay,
    'window.border': c.border,

    'base.red': c.danger,
    'base.green': c.live,
    'base.blue': c.accent,
    'base.yellow': c.warning,
    'base.magenta': mode === 'dark' ? '#BF5AF2' : '#AF52DE',
    'base.cyan': mode === 'dark' ? '#64D2FF' : '#32ADE6',
  };
}

function kitTheme() {
  const font = tokens.font.desktop;
  const theme = (name, mode) => ({
    name,
    mode,
    'font.family': font.sans,
    'font.size': font.size.base,
    'mono_font.family': font.mono,
    'mono_font.size': font.size.sm,
    radius: tokens.radius.md,
    'radius.lg': tokens.radius.lg,
    shadow: false,
    colors: kitColors(tokens.color[mode], mode),
  });

  const file = {
    $comment: HEADER,
    name: 'PairCam',
    author: 'PairCam',
    url: 'https://github.com/ismailtezal/paircam',
    themes: [theme('PairCam Dark', 'dark'), theme('PairCam Light', 'light')],
  };
  return `${JSON.stringify(file, null, 2)}\n`;
}

// --------------------------------------------------------------------------------------------
// Desktop: Rust constants for values the kit theme cannot carry
// --------------------------------------------------------------------------------------------

function rustTokens() {
  const lines = [`// ${HEADER}`, '', '#![allow(clippy::unreadable_literal)]', ''];
  const colorNames = Object.keys(tokens.color.dark);

  lines.push('/// Colours as `0xRRGGBBAA`. Pick the palette for the active mode with [`crate::palette`].');
  lines.push('#[derive(Clone, Copy, Debug)]', 'pub struct Palette {');
  for (const name of colorNames) lines.push(`    pub ${snake(name)}: u32,`);
  lines.push('}', '');

  for (const mode of ['dark', 'light']) {
    lines.push(`pub const ${mode.toUpperCase()}: Palette = Palette {`);
    for (const name of colorNames) {
      lines.push(`    ${snake(name)}: ${rgbaLiteral(tokens.color[mode][name])},`);
    }
    lines.push('};', '');
  }

  const font = tokens.font.desktop;
  lines.push('pub mod font {');
  lines.push(`    pub const SANS: &str = ${JSON.stringify(font.sans)};`);
  lines.push(`    pub const MONO: &str = ${JSON.stringify(font.mono)};`, '');
  lines.push('    /// Sizes in pixels.', '    pub mod size {');
  for (const [name, value] of Object.entries(font.size)) {
    lines.push(`        pub const ${constant(name)}: f32 = ${float(value)};`);
  }
  lines.push('    }', '', '    pub mod weight {');
  for (const [name, value] of Object.entries(tokens.font.weight)) {
    lines.push(`        pub const ${constant(name)}: f32 = ${float(value)};`);
  }
  lines.push('    }', '', '    /// Letter spacing in ems.', '    pub mod tracking {');
  for (const [name, value] of Object.entries(tokens.font.tracking)) {
    lines.push(`        pub const ${constant(name)}: f32 = ${float(value)};`);
  }
  lines.push('    }', '}', '');

  const pixelModule = (module, doc, values, prefix = '') => {
    lines.push(`/// ${doc}`, `pub mod ${module} {`);
    for (const [name, value] of Object.entries(values)) {
      lines.push(`    pub const ${prefix}${constant(name)}: f32 = ${float(value)};`);
    }
    lines.push('}', '');
  };
  pixelModule('space', 'The 4 px spacing scale, in pixels. `S_4` is 16 px.', tokens.space, 'S_');
  pixelModule('radius', 'Corner radii in pixels.', tokens.radius);
  pixelModule('size', 'Fixed control sizes in pixels.', tokens.size);

  lines.push('pub mod motion {', '    /// Durations in milliseconds.', '    pub mod duration {');
  for (const [name, value] of Object.entries(tokens.motion.duration)) {
    lines.push(`        pub const ${constant(name)}: u64 = ${value};`);
  }
  lines.push('    }', '', '    /// Cubic bezier control points.', '    pub mod easing {');
  for (const [name, value] of Object.entries(tokens.motion.easing)) {
    lines.push(`        pub const ${constant(name)}: [f32; 4] = [${value.map(float).join(', ')}];`);
  }
  lines.push('    }', '');
  lines.push('    #[derive(Clone, Copy, Debug)]', '    pub struct Spring {');
  lines.push('        /// Seconds for one oscillation if the spring were undamped.');
  lines.push('        pub response: f32,');
  lines.push('        /// 1.0 settles without overshoot; lower values bounce.');
  lines.push('        pub damping_fraction: f32,');
  lines.push('        pub stiffness: f32,', '        pub damping: f32,', '    }', '');
  lines.push('    pub mod spring {', '        use super::Spring;', '');
  for (const [name, value] of Object.entries(tokens.motion.spring)) {
    const spring = springPhysics(value);
    lines.push(`        pub const ${constant(name)}: Spring = Spring {`);
    lines.push(`            response: ${float(spring.response)},`);
    lines.push(`            damping_fraction: ${float(spring.dampingFraction)},`);
    lines.push(`            stiffness: ${float(spring.stiffness)},`);
    lines.push(`            damping: ${float(spring.damping)},`);
    lines.push('        };');
  }
  lines.push('    }', '}', '');
  return lines.join('\n');
}

// --------------------------------------------------------------------------------------------
// Phone: a typed TypeScript object
// --------------------------------------------------------------------------------------------

function typescriptTokens() {
  const font = tokens.font.mobile;
  const value = {
    color: tokens.color,
    font: {
      sans: font.sans,
      mono: font.mono,
      size: font.size,
      weight: Object.fromEntries(
        Object.entries(tokens.font.weight).map(([name, weight]) => [name, String(weight)]),
      ),
      tracking: tokens.font.tracking,
    },
    space: tokens.space,
    radius: tokens.radius,
    size: tokens.size,
    motion: {
      duration: tokens.motion.duration,
      easing: tokens.motion.easing,
      spring: Object.fromEntries(
        Object.entries(tokens.motion.spring).map(([name, spring]) => [name, springPhysics(spring)]),
      ),
    },
  };

  return [
    `// ${HEADER}`,
    '',
    `export const tokens = ${JSON.stringify(value, null, 2)} as const;`,
    '',
    'export type Tokens = typeof tokens;',
    "export type ColorMode = keyof Tokens['color'];",
    "export type ColorName = keyof Tokens['color']['dark'];",
    '',
  ].join('\n');
}

// --------------------------------------------------------------------------------------------

const outputs = [
  ['crates/ui/assets/themes/paircam.json', kitTheme()],
  ['crates/ui/src/tokens.rs', rustTokens()],
  ['apps/mobile/src/theme/tokens.ts', typescriptTokens()],
];

const check = process.argv.includes('--check');
let stale = false;

for (const [path, content] of outputs) {
  const absolute = join(root, path);
  if (check) {
    let current = null;
    try {
      current = readFileSync(absolute, 'utf8').replace(/\r\n/g, '\n');
    } catch {
      // A missing file counts as stale.
    }
    if (current !== content) {
      console.error(`out of date: ${path}`);
      stale = true;
    }
  } else {
    mkdirSync(dirname(absolute), { recursive: true });
    writeFileSync(absolute, content);
    console.log(`wrote ${relative(root, absolute).replace(/\\/g, '/')}`);
  }
}

if (stale) {
  console.error('Run `node design/tokens/build.mjs` and commit the result.');
  process.exit(1);
}
